window.REVIEW_DETAILS["ny_main-9df7a552fe6c38d1"]={"key":"ny_main-9df7a552fe6c38d1","group":"ny_main","uid":"9df7a552fe6c38d1","rank":88,"title":"calderfield highmarsh valve release pack","occupation":"production_worker_supervisors","archetype":"authored_doc","subbatch":"corpus_main","prompt":"You are the first-line production supervisor for Calderfield Logistics’ heating-valve assembly operation. Wilhelmina Petrosyan has returned the client draft because our production records and Highmarsh School District’s control register appear to give different failed-batch rates, and Kasper Crowther needs a release recommendation this week that Ivo Khouri and the contracting reviewers can use without calling operations for an explanation. For April–June, 480 batches were produced: our production record identified 24 batches that failed an inspection at any stage, while the control register recorded 18 batches finally rejected after rework and retest. For July–September, the corresponding figures were 520, 39 and 26. Of the 494 batches finally accepted in July–September, 14 lacked the newly introduced second-person release note. Frida’s review has been replaced by Wilhelmina’s recorded legal position: both the UK and Ireland require conforming product, batch traceability, recorded final disposition and retained conformity evidence; the UK uses its declaration and marking route, while Ireland uses the EU Declaration and CE route. Guidance in both jurisdictions recommends an independently documented release check, but neither expressly requires Highmarsh’s particular second-person note, and the executed supply terms do not expressly make its omission a release blocker. Highmarsh’s register makes that note mandatory from 1 November. Signed paper or electronic evidence is accepted through 31 December, while only electronic evidence is accepted from 1 January. Next-quarter volume is scheduled at 180 batches in October, 190 in November and 190 in December. Kasper wants a flat run-rate forecast based on July–September performance, with no efficiency uplift and projected batch counts rounded to the nearest whole batch after aggregate calculation. Produce `highmarsh_valve_release_pack.xlsx` as one controlled, editable briefing and review aid that consolidates the revised report and forecast. Choose explicitly whether “compliant supply” means statutory compliance alone or statutory compliance plus Highmarsh controls; either reading is defensible, but select one, show the operational consequence of the other, and finish with one release recommendation. Record what changed from the returned draft, make every repeated figure in the narrative and calculation areas agree, use only the facts above, and keep all client-facing print areas within four A4 pages. Give trustees enough plain-language guidance to use the pack without turning it into a manufacturing or regulatory tutorial. Write the file at the top level of the working directory using exactly the filename stated.\n\n---\n\nWrite your finished work to the **top level of the current working directory**, using exactly these filenames:\n\n- `highmarsh_valve_release_pack.xlsx` — A controlled, editable client briefing and forecast workbook comparing the two reporting periods, explaining the record discrepancy, projecting next-quarter outcomes and documenting one release recommendation. (Use exactly the required filename at the top level of the working directory.; Keep all client-facing print areas within four A4 pages.; Retain editable calculations rather than substituting screenshots or image-only tables.; Use only the operating, legal-review and transition facts stated in the request.; Select one definition of compliant supply and present the other only as an alternative consequence.)\n\nNothing outside those filenames is collected. A correct file written anywhere else, or under any other name, scores zero.\n","inputs":[],"gold":[{"name":"package/private/gold/highmarsh_valve_release_pack.xlsx","bytes":18580,"extension":".xlsx","url":"assets/dc6053c6a65f15279f6e2d7f9a40936bd6089de633969829efa2891eba03f348.xlsx","sha256":"dc6053c6a65f15279f6e2d7f9a40936bd6089de633969829efa2891eba03f348","preview":{"kind":"sheets","sheets":[{"name":"Release pack","row_count":88,"rows":[{"r":"1","cells":["HIGHMARSH SCHOOL DISTRICT  |  VALVE RELEASE PACK","","","","","","",""]},{"r":"2","cells":["Operational briefing and review aid  |  Calderfield Logistics heating-valve assembly","","","","","","",""]},{"r":"3","cells":["CONTROLLED BRIEFING  |  REVISED FOR DECISION REVIEW  |  JULY-SEPTEMBER ACTUALS / OCTOBER-DECEMBER PLAN","","","","","","",""]},{"r":"4","cells":[]},{"r":"5","cells":["Owner / preparer","First-line production supervisor, Calderfield Logistics","","Prepared for","Highmarsh legal, contracting and trustee stakeholders","","",""]},{"r":"6","cells":["As of","July-September actuals; next-quarter release planning","","Version / status","v1.0  |  Controlled copy  |  Revised after returned draft","","",""]},{"r":"7","cells":["Revision note","Returned draft updated: rate bases and measurement stages are explicit; the two records are reconciled without collapsing them; the July-September flat run-rate forecast, 1 November control transition, selected compliance definition and one release recommendation are added. Wilhelmina Petrosyan's recorded legal position replaces Frida's review.","","","","","",""]},{"r":"8","cells":["Purpose / users","Use this pack as the concise briefing and review aid for Kasper Crowther, Ivo Khouri, legal, contracting and trustees: compare the two valid measures, review the next-quarter exposure, then apply the release route below.","","","","","",""]},{"r":"9","cells":["Selected definition","STATUTORY COMPLIANCE + APPLICABLE HIGHMARSH CONTROLS","","","Quarter headline","=TEXT(B59,\"0\")&\" compliant batches (selected definition)\"  [缓存: 522 compliant batches (selected definition)]","",""]},{"r":"10","cells":["Release call","=TEXT(B59,\"0\")&\" is the operative forecast. Release only conforming batches with traceability, retained conformity evidence, recorded final disposition and date-appropriate second-person evidence; hold final rejects and the \"&TEXT(B55,\"0\")&\" projected control exceptions until resolved.\"  [缓存: 522 is the operative forecast. Release only conforming batches with traceability, retained conformity evidence, recorded final disposition and date-appropriate second-person evidence; hold final rejects and the 10 projected control exceptions until resolved.]","","","","","",""]},{"r":"11","cells":[]},{"r":"12","cells":["01  |  RECORD COMPARISON","","","","","","",""]},{"r":"13","cells":["Why the rates differ: the production record counts any batch that failed an inspection at any stage; the Highmarsh control register counts batches finally rejected after rework and retest. A reworked batch can therefore appear in the first measure and still be finally accepted.","","","","","","",""]},{"r":"14","cells":["Measure","Apr-Jun actual","Rate","Jul-Sep actual","Rate","Batch change","Rate change (pp)","Reader cue"]},{"r":"15","cells":["Scheduled batches (denominator)","480","n/a","520","n/a","=D15-B15  [缓存: 40]","n/a","Period volume"]},{"r":"16","cells":["Production record | any-stage inspection failures","24","=B16/B15  [缓存: 0.05]","39","=D16/D15  [缓存: 0.075]","=D16-B16  [缓存: 15]","=E16-C16  [缓存: 0.025]","Any stage, before final disposition"]},{"r":"17","cells":["Highmarsh control register | final rejects after rework + retest","18","=B17/B15  [缓存: 0.0375]","26","=D17/D15  [缓存: 0.05]","=D17-B17  [缓存: 8]","=E17-C17  [缓存: 0.0125]","Final disposition after rework and retest"]},{"r":"18","cells":["Finally accepted batches","=B15-B17  [缓存: 462]","=B18/B15  [缓存: 0.9625]","=D15-D17  [缓存: 494]","=D18/D15  [缓存: 0.95]","=D18-B18  [缓存: 32]","=E18-C18  [缓存: -0.0125000000000001]","Accepted after final disposition"]},{"r":"19","cells":["Missing second-person notes among accepted (control baseline)","—","—","14","=D19/D18  [缓存: 0.0283400809716599]","—","—","Accepted-batch denominator"]},{"r":"20","cells":[]},{"r":"21","cells":["Material change  |  July-September versus April-June","","","","","","",""]},{"r":"22","cells":["Measure","Additional batches","Rate change (pp)","Relative rate change","Interpretation","","",""]},{"r":"23","cells":["Any-stage inspection failures","=D16-B16  [缓存: 15]","=E16-C16  [缓存: 0.025]","=E16/C16-1  [缓存: 0.5]","=TEXT(D16,\"0\")&\" vs \"&TEXT(B16,\"0\")&\" affected batches; rate moved from \"&TEXT(C16,\"0.00%\")&\" to \"&TEXT(E16,\"0.00%\")&\". The figures show deterioration, not a proven root cause.\"  [缓存: 39 vs 24 affected batches; rate moved from 5.00% to 7.50%. The figures show deterioration, not a proven root cause.]","","",""]},{"r":"24","cells":["Final rejects","=D17-B17  [缓存: 8]","=E17-C17  [缓存: 0.0125]","=E17/C17-1  [缓存: 0.333333333333334]","=TEXT(D17,\"0\")&\" vs \"&TEXT(B17,\"0\")&\" final rejects; rate moved from \"&TEXT(C17,\"0.00%\")&\" to \"&TEXT(E17,\"0.00%\")&\". Cause requires separate investigation.\"  [缓存: 26 vs 18 final rejects; rate moved from 3.75% to 5.00%. Cause requires separate investigation.]","","",""]},{"r":"25","cells":["Interpretation: both measures are internally valid for their stated stage. Rework and retest can reduce the final-rejection outcome without erasing the earlier any-stage failure record. The change is observed deterioration under both measures; no causal explanation is established by the supplied facts.","","","","","","",""]},{"r":"26","cells":[]},{"r":"27","cells":["Key terms  |  plain-language reading","","","","","","",""]},{"r":"28","cells":["Any-stage failure","A batch that failed an inspection at any point in the process. It is not automatically a final reject.","","","","","",""]},{"r":"29","cells":["Final rejection","A batch rejected after any permitted rework and retest; it remains blocked from release.","","","","","",""]},{"r":"30","cells":["Accepted batch","A batch that reaches final acceptance after disposition. Release still requires the required traceability, conformity evidence and release records.","","","","","",""]},{"r":"31","cells":[]},{"r":"32","cells":["02  |  NEXT-QUARTER FORECAST","","","","","","",""]},{"r":"33","cells":["Forecast basis: July-September performance is used as a flat run-rate with no efficiency uplift. Scheduled counts are 180 in October, 190 in November and 190 in December (560 total). Counts are rounded to the nearest whole batch after aggregate calculation; component rates are not rounded before multiplication.","","","","","","",""]},{"r":"34","cells":[]},{"r":"35","cells":["Scheduled volume and control timing  |  editable inputs","","","","","","",""]},{"r":"36","cells":["Month","Forecast status","Scheduled batches","Evidence / timing","","","",""]},{"r":"37","cells":["October","Forecast","180","Before 1 November: the note is not yet mandatory in the Highmarsh register; signed paper or electronic evidence is accepted through 31 December.","","","",""]},{"r":"38","cells":["November","Forecast","190","From 1 November: the second-person note is mandatory in the Highmarsh register; signed paper or electronic evidence is accepted through 31 December.","","","",""]},{"r":"39","cells":["December","Forecast","190","The note remains mandatory; signed paper or electronic evidence is accepted through 31 December.","","","",""]},{"r":"40","cells":["Quarter total","Calculated","=SUM(C37:C39)  [缓存: 560]","180 + 190 + 190 scheduled batches","","","",""]},{"r":"41","cells":[]},{"r":"42","cells":["Run-rate inputs and control baseline","","","","","","",""]},{"r":"43","cells":["Jul-Sep any-stage failure rate","=E16  [缓存: 0.075]","Production-record basis: 39 affected batches / 520 produced.","","","","",""]},{"r":"44","cells":["Jul-Sep final-rejection rate","=E17  [缓存: 0.05]","Control-register basis: 26 final rejects / 520 produced.","","","","",""]},{"r":"45","cells":["Accepted-batch control baseline","=D18  [缓存: 494]","=D19  [缓存: 14]","=E19  [缓存: 0.0283400809716599]","14 missing notes / 494 finally accepted = approximately 2.83%.","","",""]},{"r":"46","cells":[]},{"r":"47","cells":["Forecast outcome  |  aggregate calculation","","","","","","",""]},{"r":"48","cells":["Next-quarter scheduled batches","=C40  [缓存: 560]","Total scheduled volume used by all quarter-level formulas.","","","","",""]},{"r":"49","cells":["Expected any-stage inspection failures","=ROUND(B48*B43,0)  [缓存: 42]","=TEXT(B48,\"0\")&\" x \"&TEXT(B43,\"0.00%\")&\" = \"&TEXT(B48*B43,\"0.00\")&\"; rounded after aggregation.\"  [缓存: 560 x 7.50% = 42.00; rounded after aggregation.]","","","","",""]},{"r":"50","cells":["Expected final rejects after rework + retest","=ROUND(B48*B44,0)  [缓存: 28]","=TEXT(B48,\"0\")&\" x \"&TEXT(B44,\"0.00%\")&\" = \"&TEXT(B48*B44,\"0.00\")&\"; rounded after aggregation.\"  [缓存: 560 x 5.00% = 28.00; rounded after aggregation.]","","","","",""]},{"r":"51","cells":["Statutory-only outcome: finally accepted before customer note","=B48-B50  [缓存: 532]","The statutory outcome is scheduled volume less forecast final rejects; it is shown as an alternative, not the selected operating definition.","","","","",""]},{"r":"52","cells":["November-December scheduled batches subject to note","=C38+C39  [缓存: 380]","190 + 190 = 380; the 1 November mandatory date does not apply to October.","","","","",""]},{"r":"53","cells":["Expected accepted November-December batches","=ROUND(B52*(1-B44),0)  [缓存: 361]","=TEXT(B52,\"0\")&\" x (1 - \"&TEXT(B44,\"0.00%\")&\") = \"&TEXT(B53,\"0\")&\" accepted batches at the current final-rejection rate.\"  [缓存: 380 x (1 - 5.00%) = 361 accepted batches at the current final-rejection rate.]","","","","",""]},{"r":"54","cells":["Projected missing-note cases (unrounded)","=B53*D45  [缓存: 10.2307692307692]","=TEXT(B53,\"0\")&\" x (\"&TEXT(C45,\"0\")&\" / \"&TEXT(B45,\"0\")&\") = \"&TEXT(B54,\"0.00\")&\" before nearest-whole rounding.\"  [缓存: 361 x (14 / 494) = 10.23 before nearest-whole rounding.]","","","","",""]},{"r":"55","cells":["Projected missing-note cases (rounded)","=ROUND(B54,0)  [缓存: 10]","10 projected accepted batches lack the applicable note after aggregate rounding; this is a control exception, not a product-conformity failure.","","","","",""]},{"r":"56","cells":[]},{"r":"57","cells":["One operative definition, one sensitivity","","","","","","",""]},{"r":"58","cells":["Definition","Quarter result","Decision status","","","","",""]},{"r":"59","cells":["Selected | statutory compliance + applicable Highmarsh controls","=B51-B55  [缓存: 522]","OPERATIVE: 522 compliant batches forecast. Missing applicable second-person evidence is held pending evidence or authorised resolution.","","","","",""]},{"r":"60","cells":["Alternative only | statutory compliance alone","=B51  [缓存: 532]","SENSITIVITY: 532 finally accepted batches before customer-control exceptions; not a second recommendation.","","","","",""]},{"r":"61","cells":["=\"Selection rationale: statutory requirements define the product baseline; guidance recommends an independently documented release check; the Highmarsh register makes the note mandatory from 1 November; and the executed supply terms do not expressly make omission a release blocker. The pack nevertheless adopts applicable Highmarsh controls as its operating definition. Result: \"&TEXT(B59,\"0\")&\" selected compliant batches versus \"&TEXT(B60,\"0\")&\" statutory-only, a \"&TEXT(B60-B59,\"0\")&\"-batch sensitivity only.\"  [缓存: Selection rationale: statutory requirements define the product baseline; guidance recommends an independently documented release check; the Highmarsh register makes the note mandatory from 1 November; and the executed supply terms do not expressly make omission a release blocker. The pack nevertheless adopts applicable Highmarsh controls as its operating definition. Result: 522 selected compliant batches versus 532 statutory-only, a 10-batch sensitivity only.]","","","","","","",""]},{"r":"62","cells":[]},{"r":"63","cells":["03  |  LEGAL / CONTROL STATUS AND RELEASE ROUTE","","","","","","",""]},{"r":"64","cells":["Scope note: this is an operational summary of Wilhelmina Petrosyan's recorded legal position for counsel and contracting validation, limited to the supplied UK/Ireland facts; it is not comprehensive legal advice.","","","","","","",""]},{"r":"65","cells":["Jurisdiction comparison  |  common outcomes versus route","","","","","","",""]},{"r":"66","cells":["Topic","Recorded position","","","","","",""]},{"r":"67","cells":["Common minimum outcomes","UK and Ireland both require conforming product, batch traceability, recorded final disposition and retained conformity evidence.","","","","","",""]},{"r":"68","cells":["United Kingdom","Use the UK declaration and marking route. UK minimum outcomes: conforming product, batch traceability, recorded final disposition and retained conformity evidence.","","","","","",""]},{"r":"69","cells":["Ireland","Use the EU Declaration and CE route. Ireland minimum outcomes: conforming product, batch traceability, recorded final disposition and retained conformity evidence.","","","","","",""]},{"r":"70","cells":["Independent release check","Guidance in both jurisdictions recommends an independently documented release check. That recommendation is meaningful for control, but neither jurisdiction expressly requires Highmarsh's particular second-person note.","","","","","",""]},{"r":"71","cells":["Highmarsh control register","Highmarsh makes the second-person release note mandatory from 1 November. This pack adopts applicable Highmarsh controls in its operative definition, while keeping that source distinct from statutory requirements.","","","","","",""]},{"r":"72","cells":["Executed supply terms","The executed supply terms do not expressly make omission of the note a release blocker. The selected operating position still treats missing applicable evidence as a hold pending authorised resolution.","","","","","",""]},{"r":"73","cells":[]},{"r":"74","cells":["Must / should boundary  |  practical release terms","","","","","","",""]},{"r":"75","cells":["MUST for lawful release: product conforms; batch identity and traceability are preserved; final disposition is recorded; conformity evidence is retained; and the relevant UK declaration and marking route or Ireland EU Declaration and CE route is supported.","","","","","","",""]},{"r":"76","cells":["SHOULD / pack operating rule: use an independently documented second-person release check. From 1 November the Highmarsh register makes the note mandatory; under the selected definition, an otherwise conforming batch without applicable evidence is held even though the note is not described here as an express statutory requirement.","","","","","","",""]},{"r":"77","cells":[]},{"r":"78","cells":["Transition evidence and reviewer treatment","","","","","","",""]},{"r":"79","cells":["Release timing","Register status","Accepted evidence","","Selected-pack treatment","","",""]},{"r":"80","cells":["October","Before 1 Nov","Signed paper or electronic through 31 Dec","","The note is not yet mandatory under the register; release only when the statutory baseline and retained evidence are complete. Capture the independent check where available.","","",""]},{"r":"81","cells":["November-December","Mandatory from 1 Nov","Signed paper or electronic through 31 Dec","","The note is applicable; hold an otherwise conforming batch missing the note until acceptable evidence or authorised resolution.","","",""]},{"r":"82","cells":["From 1 January","End state","Electronic only","","Only electronic second-person evidence is accepted; a paper note does not satisfy the selected control.","","",""]},{"r":"83","cells":[]},{"r":"84","cells":["Reviewer route and release recommendation","","","","","","",""]},{"r":"85","cells":["1. Confirm batch identity/traceability, conforming product, retained conformity evidence and recorded final disposition.  2. Apply the release date: October, 1 November-31 December, or from 1 January.  3. Check the evidence form above.  4. Final reject = blocked; missing applicable second-person evidence = held under this pack; complete evidence = eligible for release. An any-stage failure is not itself final disposition: where appropriate, use controlled rework, successful retest and recorded disposition before release.","","","","","","",""]},{"r":"86","cells":["FINAL RELEASE RECOMMENDATION","","","","","","",""]},{"r":"87","cells":["=TEXT(B59,\"0\")&\" compliant batches is the operative next-quarter forecast under statutory compliance plus applicable Highmarsh controls. Recommend release only of batches that conform and have batch traceability, retained conformity evidence, recorded final disposition and the evidence form applicable on the release date. Keep the \"&TEXT(B50,\"0\")&\" forecast final rejects blocked. Hold the \"&TEXT(B55,\"0\")&\" projected missing-note cases until acceptable evidence or authorised resolution is recorded. This is the single release recommendation for Kasper Crowther and the contracting reviewers.\"  [缓存: 522 compliant batches is the operative next-quarter forecast under statutory compliance plus applicable Highmarsh controls. Recommend release only of batches that conform and have batch traceability, retained conformity evidence, recorded final disposition and the evidence form applicable on the release date. Keep the 28 forecast final rejects blocked. Hold the 10 projected missing-note cases until acceptable evidence or authorised resolution is recorded. This is the single release recommendation for Kasper Crowther and the contracting reviewers.]","","","","","","",""]},{"r":"88","cells":["Calderfield Logistics  |  Highmarsh valve release pack  |  Controlled copy","","","","","","",""]}],"truncated":false}],"note":"值与公式提取，不还原原始排版；每表最多120行、30列。","embedded_image_count":0,"embedded_images":[]}}],"rubric":[{"rubric_item_id":"R01","check":"file_introspection","category":"deterministic","criterion":"The required workbook exists under the exact filename and opens as a valid XLSX file.","weight":1.0,"polarity":"credit","scaffolding":true,"cross_deliverable":false,"required":true,"evidence":"Submitted file and workbook structure.","grader_hint":"Confirm that `highmarsh_valve_release_pack.xlsx` is present at the submission root and can be opened without repair warnings."},{"rubric_item_id":"R02","check":"file_introspection","category":"deterministic","criterion":"Inputs and derived calculations remain editable, with formulas or plainly inspectable calculation logic rather than image-only content.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Workbook cells, formulas and embedded objects.","grader_hint":"Inspect the historical rates, change measures and forecast outputs. They should be editable or traceable to editable inputs; a pasted screenshot of a calculation does not satisfy this item."},{"rubric_item_id":"R03","check":"geometry","category":"deterministic","criterion":"All designated client-facing print areas render to no more than four A4 pages in total.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Workbook print settings and rendered pages.","grader_hint":"Render the designated print areas using the workbook's saved print settings and count the A4 pages. Helper cells outside the client-facing print areas need not be counted."},{"rubric_item_id":"R04","check":"judge","category":"semantic","criterion":"The workbook is professionally navigable and readable for legal, contracting and trustee readers, with restrained use of colour, legible tables and an obvious route to the comparison, forecast and recommendation.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Rendered workbook and navigation cues.","grader_hint":"Review the workbook as a client recipient. A reader should be able to find the three core components quickly without deciphering raw calculation areas or excessive manufacturing jargon."},{"rubric_item_id":"R05","check":"substring","category":"deterministic","criterion":"The pack identifies its owner or preparer, date or as-of period, version or release status, and a concise revision note describing the substantive changes made after review.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Document-control and revision text in the workbook.","grader_hint":"Look for usable document-control information and a revision note covering at least the clarified rate bases, updated comparison, forecast and selected compliance definition. Exact heading names are not required."},{"rubric_item_id":"R06","check":"judge","category":"semantic","criterion":"The pack states its purpose and intended users and functions as a reusable briefing and review aid rather than merely a calculation dump.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Opening guidance and overall workbook content.","grader_hint":"Confirm that legal, contracting and trustee users are oriented to what the pack is for and how its comparison, forecast and recommendation should be used."},{"rubric_item_id":"R07","check":"relational_predicate","category":"deterministic","criterion":"The April–June production-record measure uses 24 affected batches out of 480 and reports an any-stage failure rate equal to 24 divided by 480.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Historical comparison values and rate calculation.","grader_hint":"Verify that the displayed rate is 5.00% within normal display rounding and that 480, not another denominator, is used."},{"rubric_item_id":"R08","check":"relational_predicate","category":"deterministic","criterion":"The April–June control-register measure uses 18 final rejects out of 480 and reports a final-rejection rate equal to 18 divided by 480.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Historical comparison values and rate calculation.","grader_hint":"Verify that the displayed rate is 3.75% within normal display rounding and remains labelled as final rejection rather than any-stage failure."},{"rubric_item_id":"R09","check":"relational_predicate","category":"deterministic","criterion":"The July–September production-record measure uses 39 affected batches out of 520 and reports an any-stage failure rate equal to 39 divided by 520.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Historical comparison values and rate calculation.","grader_hint":"Verify that the displayed rate is 7.50% within normal display rounding and that the measure is not presented as final rejection."},{"rubric_item_id":"R10","check":"relational_predicate","category":"deterministic","criterion":"The July–September control-register measure uses 26 final rejects out of 520 and reports a final-rejection rate equal to 26 divided by 520.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Historical comparison values and rate calculation.","grader_hint":"Verify that the displayed rate is 5.00% within normal display rounding and that 26 is treated as a subset outcome after rework and retest."},{"rubric_item_id":"R11","check":"judge","category":"semantic","criterion":"The pack clearly defines the production-record measure as batches failing an inspection at any stage and the control-register measure as batches finally rejected after rework and retest.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Definitions, labels and explanatory narrative.","grader_hint":"The distinction must be understandable to a non-manufacturing reader and preserved wherever the two rates appear."},{"rubric_item_id":"R12","check":"judge","category":"semantic","criterion":"The apparent disagreement is reconciled as a difference in measurement stage and disposition rather than by declaring either record intrinsically wrong or forcing both measures to one value.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Narrative explaining the record discrepancy.","grader_hint":"Credit an explanation that both measures can be valid for different purposes and that reworked batches can enter the production measure without becoming final rejects."},{"rubric_item_id":"R13","check":"value_tolerance","category":"deterministic","criterion":"The material change in the production-record measure is reported as 15 additional affected batches, a 2.50 percentage-point increase and a 50.0% relative increase.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Period-change calculations.","grader_hint":"Accept ±0 batches, ±0.01 percentage points and ±0.1% on the relative increase. The percentage-point and relative-percent changes must not be interchanged."},{"rubric_item_id":"R14","check":"value_tolerance","category":"deterministic","criterion":"The material change in the control-register measure is reported as 8 additional final rejects, a 1.25 percentage-point increase and approximately a 33.3% relative increase.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Period-change calculations.","grader_hint":"Accept ±0 batches, ±0.01 percentage points and ±0.1% on the relative increase."},{"rubric_item_id":"R15","check":"judge","category":"semantic","criterion":"The change commentary distinguishes observed deterioration from an established root cause and does not invent a causal explanation unsupported by the stated facts.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Material-change commentary.","grader_hint":"Credit language that describes the direction and operational significance of the changes while treating any cause as unknown or requiring separate investigation."},{"rubric_item_id":"R16","check":"relational_predicate","category":"deterministic","criterion":"The forecast uses scheduled volumes of 180 batches in October, 190 in November and 190 in December, totalling 560 batches.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast inputs and total.","grader_hint":"Verify both the monthly values and that the total equals their sum."},{"rubric_item_id":"R17","check":"substring","category":"deterministic","criterion":"The forecast identifies July–September performance as the flat run-rate basis and states that no efficiency uplift is assumed.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast assumptions.","grader_hint":"Look for an explicit, visible assumption rather than inferring it solely from formulas."},{"rubric_item_id":"R18","check":"value_tolerance","category":"deterministic","criterion":"The next-quarter forecast shows 42 batches expected to fail an inspection at some stage.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast calculation using the current-period any-stage failure rate.","grader_hint":"Expected value is 560 × 7.50% = 42; accept ±0 batches after the required rounding convention."},{"rubric_item_id":"R19","check":"value_tolerance","category":"deterministic","criterion":"The next-quarter forecast shows 28 batches expected to be finally rejected.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast calculation using the current-period final-rejection rate.","grader_hint":"Expected value is 560 × 5.00% = 28; accept ±0 batches after the required rounding convention."},{"rubric_item_id":"R20","check":"relational_predicate","category":"deterministic","criterion":"The statutory-outcome forecast identifies 532 batches as finally accepted before applying the customer-specific second-person-note condition.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast accepted-batch calculation.","grader_hint":"Verify that accepted batches equal 560 scheduled batches minus 28 forecast final rejects."},{"rubric_item_id":"R21","check":"relational_predicate","category":"deterministic","criterion":"The control-completion baseline is shown as 14 missing second-person notes among 494 finally accepted July–September batches, with the corresponding missing-note rate calculated from those values.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Control baseline and formula.","grader_hint":"The missing-note rate should be approximately 2.83%. It must use accepted batches as its denominator, not total production or final rejects."},{"rubric_item_id":"R22","check":"relational_predicate","category":"deterministic","criterion":"The forecast applies the new mandatory customer control only to November and December, whose combined 380 scheduled batches yield 361 expected finally accepted batches at the current final-rejection rate.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Transition-period forecast logic.","grader_hint":"Verify 190 + 190 = 380 and 380 × 95% = 361. October must not be treated as already subject to the 1 November mandatory date."},{"rubric_item_id":"R23","check":"value_tolerance","category":"deterministic","criterion":"Applying the July–September missing-note rate to the 361 expected accepted November–December batches produces 10 projected accepted batches without the required note after aggregate rounding.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast control-gap calculation.","grader_hint":"The unrounded calculation is 361 × 14 ÷ 494, approximately 10.23; accept only 10 after nearest-whole aggregate rounding."},{"rubric_item_id":"R24","check":"relational_predicate","category":"deterministic","criterion":"The statutory-plus-Highmarsh-controls forecast identifies 522 compliant batches for the quarter.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Strict-definition forecast result.","grader_hint":"Verify that the result equals 532 statutory accepted batches minus 10 projected control-evidence exceptions."},{"rubric_item_id":"R25","check":"judge","category":"semantic","criterion":"The workbook presents the 532 statutory-only outcome and the 522 statutory-plus-controls outcome side by side or otherwise makes their ten-batch operational difference immediately clear.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Forecast comparison and explanatory labels.","grader_hint":"Both outcomes must be visible and accurately labelled, even though only one is adopted as the pack's main definition."},{"rubric_item_id":"R26","check":"file_introspection","category":"deterministic","criterion":"Derived rates, changes and forecasts are traceable to labelled input cells or equally transparent formulas, and changing a forecast input updates the related outputs.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Workbook formulas, named ranges or transparent calculation cells.","grader_hint":"Change a non-destructive copy of a forecast input and confirm dependent results update. Hard-coded final outputs with no traceable logic do not satisfy this item."},{"rubric_item_id":"R27","check":"substring","category":"deterministic","criterion":"The workbook states and consistently applies nearest-whole-batch rounding after aggregate calculation rather than rounding component rates prematurely.","weight":1.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Rounding note and formulas.","grader_hint":"Check both the written assumption and the control-gap calculation. The projected 10 missing notes should result from rounding the aggregate value."},{"rubric_item_id":"R28","check":"judge","category":"semantic","criterion":"Exactly one operative definition of “compliant supply” is selected: statutory compliance alone or statutory compliance plus applicable Highmarsh controls.","weight":4.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Definition statement and decision language.","grader_hint":"Either definition can receive full credit. The selection must be explicit and must not leave both definitions jointly operative."},{"rubric_item_id":"R29","check":"relational_predicate","category":"deterministic","criterion":"The selected definition controls the main compliant-supply headline, forecast total and release language throughout the workbook.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Headline metrics, forecast labels and recommendation.","grader_hint":"If statutory-only is selected, the operative compliant forecast should be 532; if statutory plus controls is selected, it should be 522. Repeated uses must agree."},{"rubric_item_id":"R30","check":"judge","category":"semantic","criterion":"The rationale for the selected definition is bounded and tied to the stated statutory minimum, guidance status, customer-control status, executed terms and transition timing.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Decision rationale.","grader_hint":"Credit either choice when its reasoning uses the supplied facts and acknowledges the competing consideration rather than treating the choice as self-evident."},{"rubric_item_id":"R31","check":"judge","category":"semantic","criterion":"The unselected definition is presented as a sensitivity, alternative interpretation or operational consequence, not as a second recommendation.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Alternative-outcome labels and surrounding narrative.","grader_hint":"The reader should understand the ten-batch consequence without being left with two equally operative positions."},{"rubric_item_id":"R32","check":"judge","category":"semantic","criterion":"The pack ends its substantive decision content with one unambiguous release recommendation that is coherent with the selected definition and forecast.","weight":4.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Final recommendation statement.","grader_hint":"The recommendation may be conditional on conformity or control evidence, but it must make one clear call and must not finish as an unresolved list of next steps."},{"rubric_item_id":"R33","check":"judge","category":"semantic","criterion":"The release logic makes clear that batches finally rejected for product nonconformity remain blocked regardless of which compliant-supply definition is selected.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Release criteria and recommendation.","grader_hint":"The customer-control debate must not be allowed to imply that a nonconforming batch can be released."},{"rubric_item_id":"R34","check":"judge","category":"semantic","criterion":"The pack explains that an any-stage inspection failure is not itself the final disposition and that a failed batch requires controlled rework where appropriate, successful retest and recorded disposition before release.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Operational guidance for interpreting and acting on failures.","grader_hint":"Look for a concise, actionable distinction rather than a technical rework tutorial."},{"rubric_item_id":"R35","check":"judge","category":"semantic","criterion":"The release guidance preserves batch identity, traceability, conformity evidence and final-disposition records as prerequisites independent of the disputed second-person note.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Release-review criteria or concise checklist.","grader_hint":"The workbook should not reduce compliance to a failure-rate threshold or to possession of the customer note alone."},{"rubric_item_id":"R36","check":"substring","category":"deterministic","criterion":"The UK comparison states the common minimum outcomes of conforming product, batch traceability, recorded final disposition and retained conformity evidence.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"UK jurisdiction summary.","grader_hint":"All four outcomes should be present or unambiguously represented in the UK portion of the comparison."},{"rubric_item_id":"R37","check":"substring","category":"deterministic","criterion":"The Ireland comparison states the common minimum outcomes of conforming product, batch traceability, recorded final disposition and retained conformity evidence.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Ireland jurisdiction summary.","grader_hint":"All four outcomes should be present or unambiguously represented in the Ireland portion of the comparison."},{"rubric_item_id":"R38","check":"substring","category":"deterministic","criterion":"The UK-specific route is identified as the UK declaration and marking route without inventing a regulation, threshold or marking exemption.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"UK jurisdiction comparison and legal-status note.","grader_hint":"Credit a concise statement consistent with the supplied review fact. The workbook need not and should not manufacture a detailed legal citation."},{"rubric_item_id":"R39","check":"substring","category":"deterministic","criterion":"The Ireland-specific route is identified as the EU Declaration and CE route without treating it as the UK route or inventing additional legal detail.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Ireland jurisdiction comparison and legal-status note.","grader_hint":"Confirm that EU Declaration and CE are associated with Ireland and remain distinct from the UK route."},{"rubric_item_id":"R40","check":"judge","category":"semantic","criterion":"The independently documented release check is accurately characterised as recommended by guidance in both jurisdictions but not expressly mandated as Highmarsh’s specific second-person note.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Jurisdiction comparison and must/should explanation.","grader_hint":"The wording must preserve both sides of the boundary: recommendation is meaningful, but it is not converted into an express statutory requirement."},{"rubric_item_id":"R41","check":"judge","category":"semantic","criterion":"The workbook distinguishes Highmarsh’s control-register requirement from statutory requirements and records that the executed supply terms do not expressly make omission of the note a release blocker.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Control-status and contract-status discussion.","grader_hint":"The customer control may be adopted as the operative definition, but its source and contractual status must still be accurately labelled."},{"rubric_item_id":"R42","check":"judge","category":"semantic","criterion":"The must/should boundary is stated in practical release terms without implying that recommended practice is optional housekeeping or, conversely, that every documented customer control is automatically law.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Decision rule and explanatory language.","grader_hint":"Credit a balanced explanation that lets reviewers understand what must be true for lawful release and what additional control the chosen operating position applies."},{"rubric_item_id":"R43","check":"judge","category":"semantic","criterion":"Transition-period guidance correctly treats the note as mandatory from 1 November and accepts either signed paper or electronic evidence through 31 December.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Dated transition guidance or reviewer instructions.","grader_hint":"The instructions must distinguish October from November–December and must not reject valid signed paper evidence during the transition."},{"rubric_item_id":"R44","check":"substring","category":"deterministic","criterion":"The end-state guidance states that only electronic second-person evidence is accepted from 1 January.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"End-state reviewer instruction.","grader_hint":"Look for a clear effective date and end-state evidence form."},{"rubric_item_id":"R45","check":"judge","category":"semantic","criterion":"The pack gives a usable exception path for an otherwise conforming batch with missing second-person evidence, and that path is consistent with the selected definition and applicable date.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Exception-handling instruction and recommendation.","grader_hint":"Under statutory-only, a documented customer-control exception and appropriate referral may coexist with release; under statutory plus controls, the batch should remain held until acceptable evidence or authorised resolution. Either path can pass if coherent."},{"rubric_item_id":"R46","check":"judge","category":"semantic","criterion":"The jurisdiction comparison is presented as an operational summary of the recorded legal position for counsel or contracting validation, not as unsupported comprehensive legal advice.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Scope statement and legal-review status.","grader_hint":"Look for concise qualification that preserves the usefulness of the comparison while acknowledging its stated source and limited scope."},{"rubric_item_id":"R47","check":"judge","category":"semantic","criterion":"Key terms—including any-stage failure, final rejection, accepted batch and the selected meaning of compliant supply—are explained in concise language suitable for trustees.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Definitions, labels and plain-language notes.","grader_hint":"A non-manufacturing reader should be able to distinguish the measures without a lengthy technical primer."},{"rubric_item_id":"R48","check":"judge","category":"semantic","criterion":"Historical inputs, forecast assumptions, calculated outputs and legal or control-status statements are visually or textually distinguished so readers can tell evidence from projection and policy choice.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Labels, formatting conventions and explanatory notes.","grader_hint":"Check that actual periods are not blended with forecast values and that the selected definition is not presented as a measured production fact."},{"rubric_item_id":"R49","check":"judge","category":"semantic","criterion":"A legal or contracting reviewer can independently use the pack to identify the applicable evidence form, classify a batch under the selected definition and locate the release recommendation without asking the author a procedural question.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"Reviewer guidance and complete workbook flow.","grader_hint":"Walk a hypothetical October case, a November paper-evidence case and a January electronic-evidence case. The workbook should provide enough concise guidance to reach the applicable treatment."},{"rubric_item_id":"R50","check":"relational_predicate","category":"deterministic","criterion":"Every figure repeated between narrative, comparison, forecast and recommendation areas agrees with its corresponding calculation and uses the same stated definition.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":true,"evidence":"All repeated counts, rates, period changes and compliant-supply totals.","grader_hint":"Cross-check repeated values, especially 5.00%, 3.75%, 7.50%, 5.00%, 560, 42, 28, 532, 10 and 522. A selected-definition headline must not conflict with the recommendation."}],"spec":{"professional_context":"Calderfield Logistics is preparing an operational release briefing for Highmarsh School District’s legal, contracting and trustee stakeholders. The pack must reconcile manufacturing and control-register measures while supporting a customer-control transition across the UK and Ireland.","difficulty_sources":["Reconciling two valid failed-batch measures that refer to different stages of disposition.","Drawing and communicating an explicit boundary between statutory compliance, recommended practice and a customer-specific control.","Supporting both a paper-or-electronic transition period and an electronic-only end state in one concise client aid.","Keeping the selected compliance definition, forecast figures and release recommendation internally consistent."],"authoring_plan":{"reference_artifacts":"Create no reference files. All local facts, dates, terminology and figures that the solver must reproduce are contained in the request.","core_imperfections":["The production record and customer control register use different but internally valid stages of measurement: any-stage inspection failure versus final rejection after rework and retest.","The current period has a materially higher rate under both measures.","A customer-specific second-person note is recommended in principle by both jurisdictional guidance regimes but is not expressly required in that form by statute.","The customer register makes the note mandatory on a future date even though the executed supply terms do not expressly make omission a release blocker.","Evidence practice is mid-transition: paper and electronic evidence coexist through year-end, followed by an electronic-only end state.","The next-quarter forecast spans one month before and two months after the customer-control effective date."],"calculation_relationships":{"historical_period_one":["Any-stage failure rate equals 24 divided by 480, or 5.00%.","Final-rejection rate equals 18 divided by 480, or 3.75%."],"historical_period_two":["Any-stage failure rate equals 39 divided by 520, or 7.50%.","Final-rejection rate equals 26 divided by 520, or 5.00%.","Finally accepted batches equal 520 minus 26, or 494.","The missing-note rate among accepted batches equals 14 divided by 494, approximately 2.834%."],"period_changes":["Any-stage failures increase by 15 batches, 2.50 percentage points and 50.0% relative to the first-period rate.","Final rejects increase by 8 batches, 1.25 percentage points and approximately 33.3% relative to the first-period rate."],"forecast":["Scheduled next-quarter volume equals 180 plus 190 plus 190, or 560 batches.","At the current-period any-stage failure rate, expected affected batches equal 560 multiplied by 7.50%, or 42.","At the current-period final-rejection rate, expected final rejects equal 560 multiplied by 5.00%, or 28.","Expected finally accepted batches under the statutory outcome equal 560 minus 28, or 532.","The customer note is mandatory only for November and December, whose combined scheduled volume is 380.","Expected accepted November–December batches equal 380 multiplied by 95%, or 361.","Projected accepted November–December batches missing the note equal 361 multiplied by 14 divided by 494, or approximately 10.23, rounded after aggregation to 10.","The statutory-plus-customer-controls compliant outcome equals 532 minus 10, or 522."]},"required_vocabulary_and_source":["The request supplies the term “compliant supply” and the two permissible definitions: statutory compliance alone, or statutory compliance plus applicable customer controls.","The request supplies the distinction between any-stage failure and final rejection.","The request supplies the UK declaration and marking route and the Ireland EU Declaration and CE route.","The request supplies the transition labels and dates; no privately invented status codes, section names or workbook labels are required."],"acceptable_solver_behaviour":["Select exactly one compliant-supply definition and use it consistently as the operative position.","Present the other definition as a sensitivity or operational consequence rather than a second recommendation.","If statutory compliance alone is selected, use 532 as the operative forecast and treat the projected ten missing-note cases as customer-control exceptions requiring documentation or referral rather than product-conformity failures.","If statutory compliance plus customer controls is selected, use 522 as the operative forecast and hold the projected ten otherwise accepted cases until acceptable control evidence or authorised resolution.","Under either choice, keep the 28 forecast final rejects blocked and require conformity, traceability and final-disposition evidence before release.","Explain the discrepancy without forcing unlike measures to reconcile or inventing a root cause.","Serve both the paper-or-electronic transition and electronic-only end state in concise reviewer guidance."],"reference_solution_verdict":"For the reference solution, adopt statutory compliance plus applicable customer controls as the operative definition, show 522 forecast compliant batches, present 532 as the statutory-only sensitivity, and recommend release only of conforming batches with the evidence applicable on their release date. The rubric must nevertheless award equal credit to a coherent statutory-only choice.","offline_validation":["Construct the gold workbook using standard spreadsheet formulas and render its client-facing areas to PDF with an offline office suite.","Verify all historical and forecast relationships by an independent Python calculation.","Walk October, November and January evidence scenarios to confirm that the transition instructions are usable.","Cross-check every repeated figure and ensure the selected definition controls the headline, forecast and recommendation.","Confirm that the rendered client-facing content does not exceed four A4 pages and that no rubric item requires internet access or an unavailable source."]},"design_constraints":{"artifact_scope":"mixed_media_bundle","structure":"strict_schema"},"reference_files":[],"deliverables":[{"deliverable_id":"release_pack","filename":"highmarsh_valve_release_pack.xlsx","media_type":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","description":"A controlled, editable client briefing and forecast workbook comparing the two reporting periods, explaining the record discrepancy, projecting next-quarter outcomes and documenting one release recommendation.","required":true,"constraints":["Use exactly the required filename at the top level of the working directory.","Keep all client-facing print areas within four A4 pages.","Retain editable calculations rather than substituting screenshots or image-only tables.","Use only the operating, legal-review and transition facts stated in the request.","Select one definition of compliant supply and present the other only as an alternative consequence."],"rendering_required":true}],"work_activity":"communicate_stakeholders","work_product":"training_material","internet_policy":"forbidden","evidence_policy":"professional_judgment"},"source_metadata":{"prompt_version":"authored_doc@v4","occupation":"production_worker_supervisors","sector":"manufacturing","task_archetype":"authored_doc","estimated_professional_hours":4.0,"gold_policy_self_report_not_verified":{"author_type":"hybrid","reviewer_policy":"The reference solution is prepared by an experienced production-operations author and independently reviewed by one manufacturing-quality reviewer and one legal or contracting communications reviewer. Reviewers must accept either compliant-supply definition when it is explicit, bounded, numerically consistent and operationally coherent.","minimum_reviewers":2,"known_limitations":["The UK and Ireland comparison is limited to the legal-review facts stated in the request and is not a comprehensive legal analysis.","The forecast is a deterministic flat run-rate projection and does not model confidence intervals, seasonality or process improvement.","The control-evidence forecast assumes that the July–September missing-note rate continues during the November–December transition."],"reference_solution_passed_rubric":true}},"validation":{"label":"成品包存在","detail":"按公开题面存在纳入抽样；不视为内容正确性验收。","formal":false,"release_ready_recorded":true,"checks":[{"check":"package_integrity","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-16T15:11:02+00:00"},{"check":"gold_isolation","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-16T15:11:02+00:00"},{"check":"artifact_format","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-16T15:11:02+00:00"},{"check":"rendering","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-16T15:11:02+00:00"}]},"source_path":"/inspire/hdd2/project/special-project-1/public/ynan/gdpval_data/corpus_main/runs/9df7a552fe6c38d1","declared_deliverables":["highmarsh_valve_release_pack.xlsx"]};
